 if(kind==='activity'){title=a?'Editar atividade':'Cadastrar atividade';const v=a||{id:'',title:'',discipline:'',from:st.project.start,to:st.project.end,qty:'',weight:'',unit:'un.',pred:[],critical:false,source:''};body=`<div class="form-grid">${field('Código da atividade','id',v.id,'text',true,a?'readonly':'')}${field('Título / descrição','title',v.title,'text',true)}${field('Disciplina / área','discipline',v.discipline)}${field('Origem (PIT, nota, etc.)','source',v.source)}${field('Início planejado','from',v.from,'date',true)}${field('Fim planejado','to',v.to,'date',true)}${field('Quantidade total','qty',v.qty,'number',true,'min="0.000001" step="any"')}${field('Unidade','unit',v.unit,'text',true)}${field('Peso do avanço','weight',v.weight,'number',true,'min="0.000001" step="any"')}${field('Predecessoras (códigos separados por vírgula)','pred',(v.pred||[]).join(', '))}</div><label class="form-field" style="margin-top:12px"><span><input name="critical" type="checkbox" ${v.critical?'checked':''}> Atividade crítica informada pelo planejamento</span></label><p class="help">O peso deve ser definido com critério técnico comum. O cadastro não será somado ao planejamento congelado até aprovação da revisão.</p>`;action='activity'}
 if(kind==='event'){title=ev?'Retificar relato':'Novo relato de acompanhamento';const v=ev||{at:localDateTime(),operationalDate:st.settings.cutoff,shift:st.settings.shift,author:st.settings.activeOperator,category:'Operação',title:'',body:'',equip:'',activityId:'',action:''};body=`<div class="form-grid">${field('Horário real da ocorrência','at',v.at,'datetime-local',true)}${field('Data operacional / turno','operationalDate',v.operationalDate,'date',true)}${select('Turno','shift',SHIFTS,v.shift,true)}${select('Operador que registrou','author',st.settings.operators,v.author,true)}${select('Categoria','category',CATS,v.category,true)}${field('Equipamento / local','equip',v.equip)}${field('Título do acontecimento','title',v.title,'text',true)}${select('Atividade vinculada','activityId',st.activities.map(a=>a.id),v.activityId)}</div>${textarea('Descrição detalhada','body',v.body,5)}${textarea('Ações tomadas / encaminhamentos','action',v.action,3)}${ev?field('Justificativa da retificação','reason','','text',true):''}<div class="notice">O relato não altera a Curva S. Para medir progresso, utilize o formulário de medição e a conferência documental.</div>`;action='event'}
 if(kind==='measure'){const v=m||{activityId:st.activities.some(x=>x.id===id)?id:'',date:st.settings.cutoff,qty:'',checked:false,author:st.settings.activeOperator,note:'',reference:''};title=m?'Retificar medição':'Nova medição de avanço';body=`<div class="form-grid">${select('Atividade','activityId',st.activities.map(a=>a.id),v.activityId,true)}${field('Data da medição','date',v.date,'date',true)}${field('Quantidade ACUMULADA (não diária)','qty',v.qty,'number',true,'min="0" step="any"')}${select('Operador que informou','author',st.settings.operators,v.author,true)}${field('Referência de comprovação','reference',v.reference||'')}${m?field('Motivo da retificação','reason','','text',true):''}</div>${textarea('Observações / fonte da medição','note',v.note||'',3)}<label class="form-field"><span><input type="checkbox" name="checked" ${v.checked?'checked':''}> Medição conferida com documento/referência aplicável (não equivale a aprovação formal)</span></label><div class="notice">A quantidade informada representa o total acumulado da atividade até a data indicada. Múltiplas medições da mesma data exigem retificação do lançamento existente. Não são somadas umas às outras.</div>`;action='measure'}
 if(kind==='shift'){const o=st.handover.find(x=>x.operationalDate===st.settings.cutoff&&x.shift===shift)||{};title='Atribuição de turno';body=`<div class="form-grid">${field('Data operacional','operationalDate',st.settings.cutoff,'date',true)}${select('Turno','shift',SHIFTS,shift,true)}${select('Responsável','author',st.settings.operators,o.author||st.settings.activeOperator,true)}</div>`;action='shift'}
