async function saveForm(e){e.preventDefault();const kind=e.target.dataset.kind,[k,...parts]=dialog.split(':'),id=decodeURIComponent(parts.join(':'));if(!storageReady||CLOUD_MODE&&!cloudReady){notice('Servidor indisponível, salvamento bloqueado.');return}const reason=form('reason');const a=st.activities.find(x=>x.id===id),ev=st.events.find(x=>x.id===id),m=st.measurements.find(x=>x.id===id),handover=st.handover.find(x=>x.id===id),issue=st.issues.find(x=>x.id===id);let actionText='';try{
 if(kind==='operator'){if(CLOUD_MODE)throw Error('O operador é identificado pelo login; não é possível trocar o nome manualmente.');const name=form('operator');if(!st.settings.operators.includes(name))throw Error('Selecione um operador.');st.settings.activeOperator=name;actionText='Operador selecionado: '+name}
 if(kind==='project'){if(!isDate(form('start'))||!isDate(form('end'))||form('start')>form('end'))throw Error('Datas inválidas.');const weekdays=[...e.target.querySelectorAll('input[name="weekday"]:checked')].map(x=>Number(x.value));if(!weekdays.length)throw Error('Selecione pelo menos um dia trabalhado.');st.project={name:form('name'),start:form('start'),end:form('end'),note:form('note')};st.settings.workdays=weekdays;actionText='Planejamento editado (ainda não aprovado como revisão)'}
 if(kind==='activity'){const code=form('id').trim().toUpperCase(),title=form('title'),qty=formNum('qty'),weight=formNum('weight'),from=form('from'),to=form('to');if(!code||!title||!Number.isFinite(qty)||qty<=0||!Number.isFinite(weight)||weight<=0||!isDate(from)||!isDate(to)||from>to)throw Error('Preencha atividade, quantidade, peso e datas válidas.');if(!a&&st.activities.some(x=>x.id===code))throw Error('Este código já existe.');const pred=form('pred').split(',').map(x=>x.trim().toUpperCase()).filter(Boolean);if(pred.includes(code))throw Error('Uma atividade não pode depender de si mesma.');const row={id:code,title,discipline:form('discipline'),source:form('source'),from,to,qty,weight,unit:form('unit')||'un.',pred,critical:Boolean(e.target.querySelector('[name="critical"]').checked)};if(a){Object.assign(a,row)}else st.activities.push(row);actionText=(a?'Atividade alterada: ':'Atividade cadastrada: ')+code}
 if(kind==='event'){const at=form('at'),date=form('operationalDate'),author=CLOUD_MODE?(ev?ev.author:cloudMember.display_name):form('author'),shift=form('shift'),title=form('title'),body=form('body');if(!at||!isDate(date)||!author||!shift||!title||!body)throw Error('Informe data, turno, operador, título e descrição.');if(ev&&!reason)throw Error('A retificação precisa de justificativa.');const obj={at,operationalDate:date,author,shift,category:form('category'),equip:form('equip'),title,body,action:form('action'),activityId:form('activityId')};if(ev){ev.history=ev.history||[];ev.history.push({at:new Date().toISOString(),reason,prev:structuredClone({...ev,history:undefined})});Object.assign(ev,obj,{revision:(ev.revision||1)+1})}else st.events.push({id:uid('EVT'),createdAt:new Date().toISOString(),revision:1,history:[],...obj});actionText=ev?'Relato retificado com justificativa':'Novo relato cadastrado'}
 if(kind==='measure'){const activityId=form('activityId'),at=st.activities.find(a=>a.id===activityId),date=form('date'),qty=formNum('qty'),author=CLOUD_MODE?(m?m.author:cloudMember.display_name):form('author'),checked=Boolean(e.target.querySelector('[name="checked"]')?.checked);if(!at||!isDate(date)||!author||!Number.isFinite(qty)||qty<0||qty>at.qty)throw Error('Quantidade acumulada inválida, fora do total da atividade ou campos obrigatórios vazios.');if(m&&!reason)throw Error('Informe motivo da retificação.');if(st.measurements.some(x=>x.id!==m?.id&&x.activityId===activityId&&x.date===date))throw Error('Já existe medição nesta data/atividade. Edite o registro existente.');if(checked){const others=st.measurements.filter(x=>x.id!==m?.id&&x.activityId===activityId&&x.checked);if(others.some(x=>x.date<date&&x.qty>qty)||others.some(x=>x.date>date&&x.qty<qty))throw Error('Quantidade acumulada conflitante com medições anteriores/posteriores. Retifique a sequência por data.')}const obj={activityId,date,qty,checked,author,note:form('note'),reference:form('reference')};if(m){m.history=m.history||[];m.history.push({at:new Date().toISOString(),reason,prev:structuredClone({...m,history:undefined})});Object.assign(m,obj,{revision:(m.revision||1)+1})}else st.measurements.push({id:uid('MED'),createdAt:new Date().toISOString(),revision:1,history:[],...obj});actionText=m?'Medição retificada':'Medição registrada (quantidade acumulada)'}
 if(kind==='shift'||kind==='handover'){const opDate=form('operationalDate'),s=form('shift'),author=form('author'),receiver=kind==='handover'?form('receiver'):'',notes=kind==='handover'?form('notes'):'';if(!isDate(opDate)||!SHIFTS.includes(s)||!author)throw Error('Informe data, turno e operador.');if(handover&&!reason)throw Error('Justifique a atualização da passagem de turno.');let target=st.handover.find(h=>h.operationalDate===opDate&&h.shift===s);const obj={key:`${opDate}|${s}`,operationalDate:opDate,shift:s,author,receiver:receiver||target?.receiver||'',notes:notes||target?.notes||''};if(target){target.history=target.history||[];target.history.push({at:new Date().toISOString(),reason:reason||'Atualização de atribuição',prev:structuredClone({...target,history:undefined})});Object.assign(target,obj)}else st.handover.push({id:uid('TRN'),createdAt:new Date().toISOString(),history:[],...obj});actionText='Turno atribuído / passagem registrada'}
 if(kind==='issue'){if(!form('title')||!form('description'))throw Error('Informe o título e a descrição.');if(issue&&!reason)throw Error('Justifique a alteração da pendência.');const obj={title:form('title'),description:form('description'),owner:form('owner'),deadline:form('deadline'),priority:form('priority'),status:form('status'),activityId:form('activityId')};if(issue){issue.history=issue.history||[];issue.history.push({at:new Date().toISOString(),reason,prev:structuredClone({...issue,history:undefined})});Object.assign(issue,obj)}else st.issues.push({id:uid('PEN'),createdAt:new Date().toISOString(),history:[],...obj});actionText=issue?'Pendência atualizada':'Pendência registrada'}
 if(kind==='joint'){const position=formNum('position'),status=form('status'),author=CLOUD_MODE?cloudMember.display_name:form('author'),date=form('date');if(!Number.isInteger(position)||position<1||position>st.settings.sh2Count||!STATUSES.includes(status)||!author||!isDate(date))throw Error('Informe posição, estado, data e operador válidos.');const old=st.joints[String(position)];if(old&&!reason)throw Error('Justifique a alteração da posição.');if(status==='Não iniciada'&&!old){actionText='Posição permanece sem informação';}else {const history=old?.history||[];if(old)history.push({at:new Date().toISOString(),reason,prev:structuredClone({...old,history:undefined})});st.joints[String(position)]={status,author,date,note:form('note'),history};actionText=`SH2 posição ${position}: ${status}`}}
 if(kind==='evidence'){if(!form('title')||!form('reference')||!isDate(form('date')))throw Error('Título, data e referência documental são obrigatórios.');st.evidences.push({id:uid('EVI'),title:form('title'),reference:form('reference'),date:form('date'),kind:form('kind'),activityId:form('activityId')});actionText='Referência documental cadastrada'}
 if(kind==='report'){if(!cloudMember?.display_name&&!st.settings.operators.includes(form('author')))throw Error('Selecione o responsável pelo relatório.');const obj={id:uid('REL'),date:reportDate,shift:reportShift,createdAt:new Date().toISOString(),author:CLOUD_MODE?cloudMember.display_name:form('author'),notes:form('notes'),base:activeBase()?.code||null,html:reportBody(reportDate,reportShift,form('notes'))};st.reports.push(obj);actionText='Relatório salvo como nova versão imutável'}
 }catch(err){notice(err.message||'Erro de validação.');return}
 const stored=await save(actionText,reason);if(!stored)return;dialog='';notice(CLOUD_MODE?'Registro confirmado no banco central.':'Registro salvo neste dispositivo.');render()}
function download(name,content,type='application/octet-stream'){const blob=new Blob([content],{type}),href=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=href;anchor.download=name;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(href),3000)}
async function backup(){await saving;const payload={format:'GV3901_LOCAL_BACKUP_V1',exportedAt:new Date().toISOString(),warning:'Banco local não criptografado. Trate como dado potencialmente sensível.',state:st};download('GV3901_parada_backup_'+today()+'.json',JSON.stringify(payload,null,2),'application/json');notice('Backup exportado. Armazene em local autorizado.')}
function makeCSV(rows){const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';return '\ufeff'+rows.map(row=>row.map(q).join(';')).join('\r\n')}
function exportCSV(){const header=['id','data_ocorrencia','data_operacional','turno','operador','categoria','equipamento','titulo','descricao','encaminhamento'];const rows=st.events.map(e=>[e.id,e.at,e.operationalDate,e.shift,e.author,e.category,e.equip,e.title,e.body,e.action]);download('GV3901_diario_'+today()+'.csv',makeCSV([header,...rows]),'text/csv;charset=utf-8');download('GV3901_medicoes_'+today()+'.csv',makeCSV([['id','atividade','data','acumulado','conferida','operador','referencia'],...st.measurements.map(m=>[m.id,m.activityId,m.date,m.qty,m.checked,m.author,m.reference])]),'text/csv;charset=utf-8');notice('CSV exportado. Backup JSON preserva mais informações e versões.')}
function exportReport(){const content=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>GV-3901 ${fmtDate(reportDate)}</title><style>body{font:14px Arial,sans-serif;color:#18384a;max-width:870px;margin:30px auto}h2{font-size:27px;color:#164d6c}h3{margin-top:25px;color:#174e65;font-size:16px}p{line-height:1.7}.keyvalue{display:grid;grid-template-columns:170px auto;gap:8px}dt{font-weight:700}dd{margin:0}.hr{border-top:1px solid #ddd;margin:19px 0}.eyebrow{color:#597b8e;font-size:11px;font-weight:bold}.report-sheet{padding:10px}@media print{body{margin:0}}</style></head><body>${reportBody()}</body></html>`;download(`GV3901_relatorio_${reportDate}_${reportShift.replace(' ','_')}.html`,content,'text/html')}
function parseDelimited(text){text=text.replace(/^\ufeff/,'');const lines=[],row=[];let token='',q=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(q&&text[i+1]==='"'){token+='"';i++}else q=!q}else if(c===';'&&!q){row.push(token);token=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(token);token='';if(row.some(x=>x.trim()))lines.push(row.slice());row.length=0}else token+=c}row.push(token);if(row.some(x=>x.trim()))lines.push(row);return lines}
function loadFromFile(callback,accept){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=async()=>{if(!input.files?.length)return;try{await callback(await input.files[0].text())}catch(err){notice(err.message||'Erro ao ler arquivo.')}};input.click()}
async function restore(){if(CLOUD_MODE){notice('Restauração total bloqueada no modo multiusuário. Use procedimento auditado de administração.');return}loadFromFile(async text=>{const data=JSON.parse(text);if(data.format!=='GV3901_LOCAL_BACKUP_V1')throw Error('Formato de backup desconhecido.');const candidate=validateState(data.state);if(!confirm(`ATENÇÃO: RESTAURAR SUBSTITUI TODOS OS DADOS LOCAIS deste dispositivo (${candidate.events.length} relatos / ${candidate.measurements.length} medições no arquivo). Deseja continuar?`))return;st=structuredClone(candidate);const ok=await save('Backup local restaurado',data.exportedAt);if(ok){notice('Backup restaurado.');render()}},'.json')}
async function importActivities(){loadFromFile(async text=>{const rows=parseDelimited(text);if(rows.length<2)throw Error('O CSV não contém atividades.');const header=rows.shift().map(x=>x.trim().toLowerCase());const expected=['id','titulo','disciplina','inicio','fim','quantidade','unidade','peso','predecessoras','critica','origem'];if(expected.some((h,i)=>header[i]!==h))throw Error('Cabeçalho diferente do modelo. Baixe o modelo CSV da aplicação.');const draft=rows.map((r,i)=>{const qty=Number(String(r[5]).replace(',','.')),weight=Number(String(r[7]).replace(',','.'));const a={id:String(r[0]||'').trim().toUpperCase(),title:r[1]?.trim()||'',discipline:r[2]?.trim()||'',from:r[3]?.trim()||'',to:r[4]?.trim()||'',qty,unit:r[6]?.trim()||'un.',weight,pred:(r[8]||'').split(',').map(x=>x.trim().toUpperCase()).filter(Boolean),critical:/^(sim|s|1|true)$/i.test(r[9]||''),source:r[10]||''};if(!a.id||!a.title||!isDate(a.from)||!isDate(a.to)||a.from>a.to||!Number.isFinite(qty)||qty<=0||!Number.isFinite(weight)||weight<=0)throw Error(`CSV: linha ${i+2} inválida (código, título, datas, quantidade ou peso).`);return a});const existing=new Set(st.activities.map(a=>a.id)),input=new Set();for(const a of draft){if(existing.has(a.id)||input.has(a.id))throw Error(`Código duplicado no planejamento: ${a.id}`);input.add(a.id)}if(!confirm(`Importar ${draft.length} atividades? A importação altera apenas o planejamento EDITÁVEL. Linhas de base congeladas são preservadas.`))return;st.activities.push(...draft);await save(`${draft.length} atividades importadas de CSV`);render();notice('Atividades importadas. Verifique pesos e dependências antes de congelar.')},'.csv,text/csv')}
function exportTemplate(){download('GV3901_modelo_atividades.csv',makeCSV([['id','titulo','disciplina','inicio','fim','quantidade','unidade','peso','predecessoras','critica','origem']]),'text/csv;charset=utf-8')}
async function freeze(){const errs=validPlan();if(errs.length){notice('Corrija pendências do planejamento: '+errs[0]);return}let reason='',code=`B${st.baselines.length}`;if(st.baselines.length){reason=prompt('Justificativa obrigatória para aprovar a revisão '+code+':')||'';if(!reason.trim()){notice('Revisão não realizada: é necessário justificar.');return}}else{if(!confirm('Confirma que as datas, pesos, quantidades, critérios e atividades foram conferidos? Será registrada a referência inicial B0 local (não constitui aprovação corporativa).'))return;reason='Primeira linha de base definida localmente após confirmação manual.'}st.baselines.push({code,at:new Date().toISOString(),reason,operator:st.settings.activeOperator||'Não definido',project:structuredClone(st.project),workdays:[...st.settings.workdays],activities:structuredClone(st.activities)});const ok=await save('Linha de base '+code+' aprovada na candidata',reason);if(ok){notice(code+' confirmada no servidor.');render()}}
async function erase(){if(CLOUD_MODE){notice('Exclusão global bloqueada no modo multiusuário.');return}const phrase=prompt('ATENÇÃO: para excluir TODOS os registros deste navegador, digite EXCLUIR. Faça backup antes.');if(phrase!=='EXCLUIR'){notice('Exclusão cancelada.');return}st=newState();await save('Banco local reiniciado');notice('Banco local limpo.');page='painel';render()}
function showInstall(){if(installPrompt){const p=installPrompt;installPrompt=null;p.prompt().then(()=>p.userChoice).then(r=>notice(r.outcome==='accepted'?'Instalação solicitada.':'Instalação cancelada.')).catch(()=>notice('Use o menu de instalação do navegador.'));return}const ios=/iPhone|iPad|iPod/i.test(navigator.userAgent);alert(ios?'Abra no Safari, toque em Compartilhar e selecione Adicionar à Tela de Início.':'No Chrome/Edge, abra o menu ⋮ e selecione Instalar aplicativo ou Adicionar à tela inicial. A instalação exige HTTPS e arquivos publicados.')}
async function actionHandler(ev){const button=ev.target.closest('[data-action]');if(!button)return;const v=button.dataset.action;if(v==='close'){dialog='';render();return}if(v==='more'){showMore=!showMore;render();return}if(v.startsWith('nav:')){page=v.slice(4);showMore=false;dialog='';location.hash='#/'+page;render();window.scrollTo(0,0);return}if(v.startsWith('modal:')){dialog=v.slice(6);showMore=false;render();return}if(v.startsWith('row:')){selectedRow=Number(v.slice(4));render();return}if(v==='apply-diary'){const d=document.getElementById('diary-date')?.value,o=document.getElementById('diary-operator')?.value;document.getElementById('diary-results').innerHTML=renderDiaryList(st.events.filter(e=>(!d||e.operationalDate===d)&&(!o||e.author===o)).sort((a,b)=>b.at.localeCompare(a.at)));return}if(v==='cloud-refresh'){if(cloudBusy||dialog){notice('Feche o formulário e aguarde a gravação antes de atualizar.');return}return cloudRefresh()}if(v==='cloud-retry')return cloudLoad();if(v==='cloud-signout')return cloudSignOut();if(v==='cloud-export'){if(!cloudPending)return;download('GV3901_EDICAO_NAO_SINCRONIZADA_'+today()+'.json',JSON.stringify(cloudPending,null,2),'application/json');return}if(v==='cloud-discard'){if(!confirm('Descartar todas as edições não confirmadas e carregar o servidor?'))return;cloudConflict=false;cloudPending=null;dialog='';return cloudRefresh()}if(v==='freeze')return freeze();if(v==='backup')return backup();if(v==='restore')return restore();if(v==='erase')return erase();if(v==='export-csv')return exportCSV();if(v==='export-report')return exportReport();if(v==='print-report'){window.print();return}if(v==='install')return showInstall();if(v==='import-activities')return importActivities();if(v==='template-activities')return exportTemplate()}
document.addEventListener('click',actionHandler);document.addEventListener('submit',e=>{if(e.target.id==='active-form')saveForm(e);if(e.target.id==='cloud-login-form'){e.preventDefault();cloudSignIn(e.target.elements.email.value.trim(),e.target.elements.password.value)}});
document.addEventListener('change',async e=>{const filter=e.target.dataset.filter;if(!filter)return;const value=e.target.value;if(filter==='cutoff'){if(!isDate(value)){notice('Data inválida.');return}st.settings.cutoff=value;if(CLOUD_MODE)localStorage.setItem('gv3901_pref_cutoff',value);else await save()}else if(filter==='activeOperator'){if(CLOUD_MODE){notice('O operador ativo é determinado pela conta autenticada.');return}else{st.settings.activeOperator=value;await save('Operador ativo selecionado',value)}}else if(filter==='reportDate')reportDate=value;else if(filter==='reportShift')reportShift=value;else if(filter==='scenario')chartScenario=value;render()});
window.addEventListener('hashchange',()=>{const path=location.hash.slice(2);if(NAV.some(x=>x[0]===path)){page=path;dialog='';showMore=false;render()}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialog){dialog='';render()}});
